#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_no_resize_needed(void) {
    // Setup: create buffer with enough space for append (self->len > needed)
    // Initial content: "foo", buffer size: 10
    buffer_t *buf = helper_create_buffer_with_content_and_size("foo", 10);
    TEST_ASSERT_NOT_NULL(buf);

    const char *to_append = "bar";
    size_t append_len = 3;

    // Test: call buffer_append_n
    int ret = buffer_append_n(buf, to_append, append_len);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, ret);
    // Buffer should now contain "foobar"
    helper_assert_buffer_content(buf, "foobar");
    // Buffer string length should be 6
    helper_assert_buffer_length(buf, 6);
    // Buffer size should remain 10
    helper_assert_buffer_size(buf, 10);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_no_resize_needed);
    return UNITY_END();
}


