// Asserts that the buffer's content matches the expected string.
void helper_assert_buffer_content(buffer_t *buf, const char *expected) {
    if (strcmp(buf->data, expected) != 0) {
        printf("Buffer content mismatch!
Expected: '%s'
Actual:   '%s'
", expected, buf->data);
        assert(0);
    }
}

// Asserts that the buffer's string length matches the expected value.
void helper_assert_buffer_length(buffer_t *buf, size_t expected_length) {
    size_t actual_length = buffer_length(buf);
    if (actual_length != expected_length) {
        printf("Buffer length mismatch! Expected: %zu, Actual: %zu
", expected_length, actual_length);
        assert(0);
    }
}

// Asserts that the buffer's allocated size matches the expected value.
void helper_assert_buffer_size(buffer_t *buf, size_t expected_size) {
    size_t actual_size = buffer_size(buf);
    if (actual_size != expected_size) {
        printf("Buffer size mismatch! Expected: %zu, Actual: %zu
", expected_size, actual_size);
        assert(0);
    }
}

// ========== Created - Utility Operations ==========

// Creates a new buffer initialized with the given string content.
buffer_t *helper_create_buffer_with_content(char *str) {
    return buffer_new_with_copy(str);
}

// Creates a new buffer with specified size and initial content.
buffer_t *helper_create_buffer_with_content_and_size(const char *str, size_t size) {
    buffer_t *buf = buffer_new_with_size(size);
    if (!buf) return NULL;
    strncpy(buf->data, str, size - 1);
    buf->data[size - 1] = '\0';
    return buf;
}

// Frees the given buffer and its memory.
void helper_free_buffer(buffer_t *buf) {
    buffer_free(buf);
}


